using System;
using System.Security.Cryptography;
public static class WebhookSignature {
    public static bool Verify(byte[] rawBody, byte[] signature, byte[] key) {
        if (rawBody.Length > 1048576 || key.Length < 32 || signature.Length != 32) return false;
        using var mac = new HMACSHA256(key);
        byte[] expected = mac.ComputeHash(rawBody);
        bool valid = CryptographicOperations.FixedTimeEquals(expected, signature);
        CryptographicOperations.ZeroMemory(expected);
        return valid;
    }
}

